import org.jsoup.Connection;
import org.jsoup.helper.DataUtil;
import org.jsoup.helper.UrlBuilder;
import org.junit.Assert;
import org.junit.Test;

import java.io.UnsupportedEncodingException;
import java.net.URISyntaxException;
import java.net.URL;

public class UrlBuilderTest {

    @Test
    public void buildWithNullUrlTest() throws URISyntaxException {
        URL nullUrl = null;
        UrlBuilder urlBuilder = new UrlBuilder(nullUrl);
        URL builtUrl = urlBuilder.build();
        Assert.assertNull(builtUrl);
    }

    @Test
    public void buildWithValidUrlTest() throws URISyntaxException {
        URL validUrl = new URL("https://example.com/path?param1=value1");
        UrlBuilder urlBuilder = new UrlBuilder(validUrl);
        URL builtUrl = urlBuilder.build();
        Assert.assertEquals(validUrl, builtUrl);
    }

    @Test
    public void appendKeyValWithNullKeyValTest() throws UnsupportedEncodingException {
        Connection.KeyVal nullKeyVal = null;
        UrlBuilder urlBuilder = new UrlBuilder(new URL("https://example.com/path"));
        urlBuilder.appendKeyVal(nullKeyVal);
        Assert.assertEquals("https://example.com/path", urlBuilder.build().toString());
    }

    @Test
    public void appendKeyValWithValidKeyValTest() throws UnsupportedEncodingException {
        Connection.KeyVal validKeyVal = new Connection.KeyVal("key", "value");
        UrlBuilder urlBuilder = new UrlBuilder(new URL("https://example.com/path"));
        urlBuilder.appendKeyVal(validKeyVal);
        Assert.assertEquals("https://example.com/path?key=value", urlBuilder.build().toString());
    }

}
```

This code provides unit tests for the `UrlBuilder` class. It includes tests for the `build` and `appendKeyVal` methods. The tests cover various edge cases, including null values and valid values.
